/* Network-first service worker: keep pages fresh while retaining offline fallback. */
importScripts("./assets/js/data/swconf.js");

const cacheName = swconf.cacheName;

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    if (!swconf.purge) {
      const cache = await caches.open(cacheName);
      await cache.addAll(swconf.resources);
    }

    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.map((key) => {
      if (swconf.purge || key !== cacheName) return caches.delete(key);
      return Promise.resolve();
    }));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  const url = new URL(request.url);

  if (request.method !== "GET" || url.origin !== self.location.origin || request.headers.has("range")) {
    return;
  }
  if (swconf.purge) return;

  const isExcludedPath = swconf.interceptor.paths.some((path) => url.pathname.startsWith(path));
  const isExcludedUrl = swconf.interceptor.urlPrefixes.some((prefix) => url.href.startsWith(prefix));
  if (isExcludedPath || isExcludedUrl) return;

  event.respondWith((async () => {
    const cache = await caches.open(cacheName);

    try {
      const response = await fetch(request, { cache: "no-cache" });
      if (response.ok && !swconf.purge) {
        await cache.put(request, response.clone()).catch(() => {});
      }
      return response;
    } catch (error) {
      const cached = await cache.match(request);
      if (cached) return cached;
      if (request.mode === "navigate") {
        return (await cache.match("/")) || Response.error();
      }
      return Response.error();
    }
  })());
});
